// Navigation Menu Functionality
document.addEventListener('DOMContentLoaded', function() {
    const navItems = document.querySelectorAll('.nav-item');
    const sections = document.querySelectorAll('section[id]');
    
    // Smooth scrolling for navigation links
    navItems.forEach(navItem => {
        navItem.addEventListener('click', function(e) {
            e.preventDefault();
            
            const targetId = this.getAttribute('href').substring(1);
            const targetSection = document.getElementById(targetId);
            
            if (targetSection) {
                // Update active nav item
                navItems.forEach(item => item.classList.remove('active'));
                this.classList.add('active');
                
                // Smooth scroll to section
                targetSection.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            }
        });
    });
    
    // Update active nav item on scroll
    function updateActiveNavOnScroll() {
        let current = '';
        const scrollPosition = window.pageYOffset + 200; // Adjusted offset for better detection
        
        sections.forEach(section => {
            const sectionTop = section.offsetTop;
            const sectionHeight = section.offsetHeight;
            
            if (scrollPosition >= sectionTop && scrollPosition < sectionTop + sectionHeight) {
                current = section.getAttribute('id');
            }
        });
        
        // If we're at the top of the page, highlight the first section
        if (window.pageYOffset < 100) {
            current = 'profil';
        }
        
        // Update nav items
        navItems.forEach(navItem => {
            navItem.classList.remove('active');
            const href = navItem.getAttribute('href');
            if (href === `#${current}`) {
                navItem.classList.add('active');
            }
        });
    }
    
    // Scroll progress bar function
    function updateScrollProgress() {
        const scrollTop = window.pageYOffset;
        const docHeight = document.documentElement.scrollHeight - window.innerHeight;
        const scrollPercent = (scrollTop / docHeight) * 100;
        
        const progressBar = document.querySelector('.scroll-progress-bar');
        if (progressBar) {
            progressBar.style.width = scrollPercent + '%';
        }
    }
    
    // Listen for scroll events with throttling for performance
    let scrollTimeout;
    window.addEventListener('scroll', function() {
        if (scrollTimeout) {
            clearTimeout(scrollTimeout);
        }
        scrollTimeout = setTimeout(() => {
            updateActiveNavOnScroll();
            updateScrollProgress();
        }, 10);
    });
    
    // Initial calls
    updateActiveNavOnScroll();
    updateScrollProgress();
});

// Projects Section Functionality
document.addEventListener('DOMContentLoaded', function() {
    // Tab switching functionality
    const tabBtns = document.querySelectorAll('.tab-btn');
    const projectCards = document.querySelectorAll('.project-card');
    const sectionDescription = document.getElementById('section-description');
    
    const descriptions = {
        projects: "This section contains the projects completed by me, using major Technologies.",
        achievements: "Recognition and certifications earned throughout my professional journey.",
        hobbies: "Personal projects and interests that fuel my passion for development."
    };
    
    tabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            const category = btn.getAttribute('data-category');
            
            // Update active tab
            tabBtns.forEach(tab => tab.classList.remove('active'));
            btn.classList.add('active');
            
            // Update description
            if (sectionDescription) {
                sectionDescription.textContent = descriptions[category];
            }
            
            // Show/hide cards based on category
            projectCards.forEach(card => {
                if (card.getAttribute('data-category') === category) {
                    card.style.display = 'block';
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0)';
                    }, 50);
                } else {
                    card.style.opacity = '0';
                    card.style.transform = 'translateY(20px)';
                    setTimeout(() => {
                        card.style.display = 'none';
                    }, 300);
                }
            });
            
            // Reset tech filter
            const techBadges = document.querySelectorAll('.tech-badge');
            techBadges.forEach(badge => badge.classList.remove('active'));
            document.querySelector('.tech-badge[data-tech="all"]').classList.add('active');
        });
    });
    
    // Technology filter functionality
    const techBadges = document.querySelectorAll('.tech-badge');
    
    techBadges.forEach(badge => {
        badge.addEventListener('click', () => {
            const tech = badge.getAttribute('data-tech');
            const activeCategory = document.querySelector('.tab-btn.active').getAttribute('data-category');
            
            // Update active badge
            techBadges.forEach(b => b.classList.remove('active'));
            badge.classList.add('active');
            
            // Filter cards
            const categoryCards = document.querySelectorAll(`[data-category="${activeCategory}"]`);
            
            categoryCards.forEach(card => {
                const cardTechnologies = card.getAttribute('data-technologies');
                
                if (tech === 'all' || (cardTechnologies && cardTechnologies.includes(tech))) {
                    card.style.display = 'block';
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0)';
                    }, 50);
                } else {
                    card.style.opacity = '0';
                    card.style.transform = 'translateY(20px)';
                    setTimeout(() => {
                        card.style.display = 'none';
                    }, 300);
                }
            });
        });
    });
    
    // Initialize card animations
    projectCards.forEach(card => {
        card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
    });
});

// Education Section Functionality
document.addEventListener('DOMContentLoaded', function() {
    const eduTabBtns = document.querySelectorAll('.edu-tab-btn');
    const educationTimeline = document.getElementById('education-timeline');
    const certificationsTimeline = document.getElementById('certifications-timeline');
    
    eduTabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            const category = btn.getAttribute('data-category');
            
            // Update active tab
            eduTabBtns.forEach(tab => tab.classList.remove('active'));
            btn.classList.add('active');
            
            // Show/hide timelines with animation
            if (category === 'education') {
                // Hide certifications
                if (certificationsTimeline) {
                    certificationsTimeline.style.opacity = '0';
                    certificationsTimeline.style.transform = 'translateY(20px)';
                    setTimeout(() => {
                        certificationsTimeline.style.display = 'none';
                    }, 300);
                }
                
                // Show education
                if (educationTimeline) {
                    setTimeout(() => {
                        educationTimeline.style.display = 'block';
                        setTimeout(() => {
                            educationTimeline.style.opacity = '1';
                            educationTimeline.style.transform = 'translateY(0)';
                        }, 50);
                    }, 300);
                }
            } else if (category === 'certifications') {
                // Hide education
                if (educationTimeline) {
                    educationTimeline.style.opacity = '0';
                    educationTimeline.style.transform = 'translateY(20px)';
                    setTimeout(() => {
                        educationTimeline.style.display = 'none';
                    }, 300);
                }
                
                // Show certifications
                if (certificationsTimeline) {
                    setTimeout(() => {
                        certificationsTimeline.style.display = 'block';
                        setTimeout(() => {
                            certificationsTimeline.style.opacity = '1';
                            certificationsTimeline.style.transform = 'translateY(0)';
                        }, 50);
                    }, 300);
                }
            }
        });
    });
    
    // Initialize timeline animations
    const timelines = [educationTimeline, certificationsTimeline];
    timelines.forEach(timeline => {
        if (timeline) {
            timeline.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
            timeline.style.opacity = timeline.id === 'education-timeline' ? '1' : '0';
            timeline.style.transform = 'translateY(0)';
        }
    });
});

